initJs:
function(container, apiUrl, tables) {
  // テスト履歴の再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.実行日時 || ""}</td>
        <td>${r.モデル名 || ""}</td>
        <td>${r.テスト期間 || ""}</td>
        <td>${r.対象店舗数 || ""}</td>
        <td>${r.MAPE || ""}</td>
        <td>${r.RMSE || ""}</td>
        <td>${r.実行時間 || ""}</td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データの描画
  renderTestHistory(tables[0]?.records || []);

  // 全店舗選択チェックボックスの処理
  const selectAllStores = container.querySelector("#select-all-stores");
  const storeCheckboxes = container.querySelectorAll(".store-checkbox");

  selectAllStores.addEventListener("change", function() {
    storeCheckboxes.forEach(checkbox => {
      checkbox.checked = this.checked;
    });
  });

  // 全カテゴリ選択チェックボックスの処理
  const selectAllCategories = container.querySelector("#select-all-categories");
  const categoryCheckboxes = container.querySelectorAll(".category-checkbox");

  selectAllCategories.addEventListener("change", function() {
    categoryCheckboxes.forEach(checkbox => {
      checkbox.checked = this.checked;
    });
  });

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => {
      errorDiv.classList.add("hidden");
    }, 5000);
  }

  // ローディング表示制御
  function showLoading(show) {
    const loadingDiv = container.querySelector("#loading-indicator");
    if (show) {
      loadingDiv.classList.remove("hidden");
    } else {
      loadingDiv.classList.add("hidden");
    }
  }

  // バリデーション関数
  function validateTestConfig() {
    const modelSelect = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const selectedStores = container.querySelectorAll(".store-checkbox:checked");
    const selectedCategories = container.querySelectorAll(".category-checkbox:checked");
    const selectedDataset = container.querySelector('input[name="dataset"]:checked');

    if (!modelSelect) {
      showError("モデルが選択されていません。モデルを選択してください。");
      return false;
    }

    if (!startDate || !endDate) {
      showError("テスト期間を設定してください。");
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return false;
    }

    if (selectedStores.length === 0) {
      showError("対象店舗を選択してください。");
      return false;
    }

    if (selectedCategories.length === 0) {
      showError("対象商品カテゴリを選択してください。");
      return false;
    }

    if (!selectedDataset) {
      showError("テストデータセットが選択されていません");
      return false;
    }

    return true;
  }

  // 予測精度指標の更新
  function updateMetrics(mape, rmse, mae, r2) {
    container.querySelector("#mape-value").textContent = mape + "%";
    container.querySelector("#rmse-value").textContent = rmse;
    container.querySelector("#mae-value").textContent = mae;
    container.querySelector("#r2-value").textContent = r2;
  }

  // 実行時間の更新
  function updateExecutionTime(time) {
    container.querySelector("#execution-time").textContent = time + "秒";
  }

  // モデルパラメータの更新
  function updateModelParameters(params) {
    container.querySelector("#training-period").textContent = params.trainingPeriod || "-";
    container.querySelector("#feature-count").textContent = params.featureCount || "-";
    container.querySelector("#algorithm").textContent = params.algorithm || "-";
    container.querySelector("#hyperparameters").textContent = params.hyperparameters || "-";
  }

  // 比較グラフの描画
  function drawComparisonChart(actualData, predictedData) {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // グラフの設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // データの最大値・最小値を計算
    const allValues = [...actualData, ...predictedData];
    const maxValue = Math.max(...allValues);
    const minValue = Math.min(...allValues);
    const valueRange = maxValue - minValue;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 実績値の線グラフ
    if (actualData.length > 0) {
      ctx.strokeStyle = '#4a9eff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      actualData.forEach((value, index) => {
        const x = padding + (index / (actualData.length - 1)) * chartWidth;
        const y = canvas.height - padding - ((value - minValue) / valueRange) * chartHeight;
        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
    }

    // 予測値の線グラフ
    if (predictedData.length > 0) {
      ctx.strokeStyle = '#ff6a00';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);
      ctx.beginPath();
      predictedData.forEach((value, index) => {
        const x = padding + (index / (predictedData.length - 1)) * chartWidth;
        const y = canvas.height - padding - ((value - minValue) / valueRange) * chartHeight;
        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
      ctx.setLineDash([]);
    }

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '14px Arial';
    ctx.fillText('実績値', canvas.width - 150, 30);
    ctx.fillText('予測値', canvas.width - 150, 50);

    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(canvas.width - 170, 25);
    ctx.lineTo(canvas.width - 155, 25);
    ctx.stroke();

    ctx.strokeStyle = '#ff6a00';
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(canvas.width - 170, 45);
    ctx.lineTo(canvas.width - 155, 45);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // テスト実行ボタンのイベントリスナー
  container.querySelector("#btn-test-execute").addEventListener("click", async function() {
    if (!validateTestConfig()) {
      return;
    }

    showLoading(true);

    try {
      // テスト実行のシミュレーション
      await new Promise(resolve => setTimeout(resolve, 3000));

      // サンプル結果の表示
      updateMetrics(12.5, 45.2, 38.7, 0.85);
      updateExecutionTime(127);
      updateModelParameters({
        trainingPeriod: "2023/01/01 - 2023/12/31",
        featureCount: 25,
        algorithm: "Random Forest",
        hyperparameters: "n_estimators=100, max_depth=10"
      });

      // サンプルデータでグラフ描画
      const actualData = [100, 120, 95, 140, 110, 130, 105, 125, 115, 135];
      const predictedData = [105, 115, 100, 135, 115, 125, 110, 120, 120, 130];
      drawComparisonChart(actualData, predictedData);

      // テスト履歴に追加
      const testResult = {
        実行日時: new Date().toLocaleString(),
        モデル名: container.querySelector("#model-select").value,
        テスト期間: `${container.querySelector("#start-date").value} - ${container.querySelector("#end-date").value}`,
        対象店舗数: container.querySelectorAll(".store-checkbox:checked").length,
        MAPE: "12.5%",
        RMSE: "45.2",
        実行時間: "127秒"
      };

      const saved = await window.aivicApi.save(0, testResult);
      if (saved) {
        const rows = await window.aivicApi.list(0);
        if (rows) renderTestHistory(rows);
      }

    } catch (error) {
      showError("テスト実行中にエラーが発生しました: " + error.message);
    } finally {
      showLoading(false);
    }
  });

  // エクスポートボタンのイベントリスナー
  container.querySelector("#btn-test-export").addEventListener("click", async function() {
    try {
      const rows = await window.aivicApi.list(0);
      if (!rows || rows.length === 0) {
        showError("エクスポートするデータがありません");
        return;
      }

      const headers = ["実行日時", "モデル名", "テスト期間", "対象店舗数", "MAPE", "RMSE", "実行時間"];
      const csvContent = "\uFEFF" + headers.join(",") + "\n" + 
        rows.map(row => [
          row.実行日時 || "",
          row.モデル名 || "",
          row.テスト期間 || "",
          row.対象店舗数 || "",
          row.MAPE || "",
          row.RMSE || "",
          row.実行時間 || ""
        ].map(field => `"${field}"`).join(",")).join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "model_test_results.csv";
      link.click();

    } catch (error) {
      showError("エクスポート中にエラーが発生しました: " + error.message);
    }
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async function(e) {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;

      try {
        await window.aivicApi.delete(0, deleteBtn.dataset.id);
        const rows = await window.aivicApi.list(0);
        if (rows) renderTestHistory(rows);
      } catch (error) {
        showError("削除中にエラーが発生しました: " + error.message);
      }
    }

    const viewDetailBtn = e.target.closest(".view-detail-btn");
    if (viewDetailBtn) {
      // 詳細表示の実装（今回は省略）
      showError("詳細表示機能は実装中です");
    }
  });

  // 初期データの読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) renderTestHistory(rows);
  });
}
